        c = []
        f = []
        for i in range(n):
            l = list(map(int, input().split()))
            p.append(l[0])
            c.append(l[1])
            f.append(set(l[2:]))
        for i in range(n):
            for j in range(n):
                if p[i] >= p[j]:
                    if f[j].issuperset(f[i]):
                        return 'Yes'
        return 'No'
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys_input = io.StringIO(text)
        sys.stdin = sys_input
        with redirect_stdout(output):
            result = program()
            print(result)
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

